    function alignFragment(index, value, internal = false) {
      const i = Number(index);
      const v = Number(value);
      if (!Number.isInteger(i) || i < 0 || i > 2 || !Number.isFinite(v)) return false;
      if (state.actIndex !== 1) return false;
      if (!internal) takeControl();
      state.fragments[i] = clamp(v, 0, 1);
      const wasAligned = state.aligned[i];
      state.aligned[i] = Math.abs(state.fragments[i] - TARGETS[i]) <= TOLERANCE;
      if (state.aligned[i]) state.fragments[i] = TARGETS[i];

      if (!wasAligned && state.aligned[i] && !selfTesting) {
        a11yStatus.textContent = `Fragment ${i + 1} aligned.`;
      }

      if (state.aligned.every(Boolean)) {
        if (state.alignedSince === null) state.alignedSince = state.actTime;
      } else {
        state.alignedSince = null;
      }
      if (!internal) updateUI(true);
      return state.aligned[i];
    }

    function choose(ending, internal = false) {
      if (ending !== 'answer' && ending !== 'silent') return false;
      if (!state.choiceAvailable || state.actIndex !== 2) return false;
      if (!internal) takeControl();
      state.ending = ending;
      state.choiceAvailable = false;
      setAct(3);
      if (!selfTesting) a11yStatus.textContent = ending === 'answer' ? 'The operator answers.' : 'The operator stays silent.';
